use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    match input {
        serde_json::Value::String(s) => {
            if s.len() % 2 != 0 {
                return None;
            }
            let mut result = Vec::new();
            for i in 0..s.len() {
                let c = match s.chars().nth(i).unwrap() {
                    '0'..='9' => s[i] as u8 - '0' as u8,
                    'a'..='f' => s[i] as u8 - 'a' as u8 + 10,
                    'A'..='F' => s[i] as u8 - 'A' as u8 + 10,
                    _ => return None,
                };
                if c < 0 || c > 255 {
                    return None;
                }
                result.push(c);
            }
            json!(result)
        }
        _ => json!(None),
    }
}
